#pragma once
#include <circuit/gameplay/block_registry.hpp>
#include <cstddef>
#include <cstdint>

// Tables of the block registry, generated by tools/compile_block_registry.py
// into block_registry_data.cpp. See include/circuit/gameplay/block_registry.hpp.
namespace circuit::gameplay::registry::data {

struct BlockData {
    const char* name;
    std::uint16_t first_property;
    std::uint8_t property_count;
    std::uint32_t first_state;
    std::uint32_t state_count;
    std::uint32_t default_offset;
    float hardness;
    std::uint8_t opaque;
    std::uint8_t tool;
    std::uint8_t tier;
    float resistance;
    std::uint8_t push;       // registry::PushClass
    std::uint8_t instrument; // registry::Instrument
    std::uint8_t conductor;  // registry::Conductor
    std::uint8_t connector;  // bits 0-2 registry::Connector; bit 3 walls keep their post under it; bit 4 soil
};
struct PropertyData {
    const char* name;
    std::uint16_t first_value;
    std::uint16_t value_count;
};
// One block of a version, in the version's wire order.
struct VersionBlock {
    std::uint32_t first_wire;
    std::uint16_t block;
};
// A light occlusion shape: per face, the 16x16 cells it covers.
struct LightFaces {
    std::uint64_t faces[6][4];
};
using CollisionBox = registry::Box;
struct CollisionShape {
    std::uint32_t first_box;
    std::uint16_t box_count;
};
// A state whose collision shape in one release differs from its own.
struct CollisionOverride {
    const char* release;
    std::uint32_t state;
    std::uint16_t shape;
};
// A state whose shape in one release supports otherwise than its own.
struct SupportOverride {
    const char* release;
    std::uint32_t state;
    std::uint8_t support;
};
struct VersionTable {
    const char* release;
    const VersionBlock* blocks;
    std::uint32_t block_count;
    std::uint32_t state_count; // wire state ids are 0 to state_count - 1
};

extern const char* const registry_id;
extern const BlockData blocks[];
extern const std::uint32_t block_count;
extern const std::uint32_t state_count;
extern const PropertyData properties[];
extern const char* const values[];
extern const std::uint8_t shapes[];
extern const std::uint8_t join_faces[];
extern const std::uint8_t support[];
extern const std::uint8_t light[];
extern const std::uint16_t light_shape[];
extern const LightFaces light_faces[];
extern const std::uint32_t light_shape_count;
extern const CollisionBox collision_boxes[];
extern const CollisionShape collision_shapes[];
extern const std::uint16_t collision_shape[];
extern const CollisionOverride collision_overrides[];
extern const std::size_t collision_override_count;
extern const SupportOverride support_overrides[];
extern const std::size_t support_override_count;
extern const VersionTable versions[];
extern const std::size_t version_count;

} // namespace circuit::gameplay::registry::data
